  jump(jump: DiagramJump): DiagramJump {
    return this.mapJump(jump, id => this.anchorId(id));
  }
  resolveJump(jump: DiagramJump): DiagramJump {
    return this.mapJump(jump, id => this.resolveAnchorId(id));
  }
  private mapJump(jump: DiagramJump, map: (id: string) => string): DiagramJump {
    return { ...jump, source: { ...jump.source, ...(jump.source.contentNodeId ? { contentNodeId: map(jump.source.contentNodeId) } : {}) },
      target: { ...jump.target, ...(jump.target.contentNodeId ? { contentNodeId: map(jump.target.contentNodeId) } : {}) } };
  }
}
"},{"path":"infrastructure/mapping/agent/canvasSessionBridge.ts","text":"import { randomUUID } from 'node:crypto';
import type { CanvasSessionPort } from '../../../application/mapping/agent/ports';
import type { CanvasCommand, CanvasDescriptor } from '../../../domain/mapping/agent/contracts';
export class CanvasSessionBridge implements CanvasSessionPort {
  private canvases = new Map<string, { descriptor: CanvasDescriptor; touched: number; commands: CanvasCommand[]; wake?: () => void }>();
  private pending = new Map<string, { canvasId: string; resolve: (value: unknown) => void; reject: (error: Error) => void; timer: ReturnType<typeof setTimeout> }>();
  register(descriptor: CanvasDescriptor) {
    const old = this.canvases.get(descriptor.canvasId);
    if (old) { old.descriptor = structuredClone(descriptor); old.touched = Date.now(); }
    else this.canvases.set(descriptor.canvasId, { descriptor: structuredClone(descriptor), touched: Date.now(), commands: [] });
  }
  list() {
    for (const [id, entry] of this.canvases) if (Date.now() - entry.touched > 35000) this.unregister(id);
    return [...this.canvases.values()].map(entry => structuredClone(entry.descriptor));
  }
  async poll(canvasId: string) {
    const entry = this.canvases.get(canvasId);
    if (!entry) throw new Error('CANVAS_UNAVAILABLE');
    entry.touched = Date.now();
    if (!entry.commands.length) await new Promise<void>(resolve => {
      entry.wake?.();
      const timer = setTimeout(done, 15000);
      function done() { clearTimeout(timer); if (entry!.wake === done) entry!.wake = undefined; resolve(); }
      entry.wake = done;
    });
    entry.touched = Date.now();
    return entry.commands.splice(0);
  }
  dispatch(canvasId: string, command: Omit<CanvasCommand, 'id'>): Promise<unknown> {
    this.list();
    const entry = this.canvases.get(canvasId);
    if (!entry) return Promise.reject(new Error('CANVAS_UNAVAILABLE: open Mapping and attach again'));
    if (this.pending.size >= 100) return Promise.reject(new Error('Too many pending canvas commands'));
    return new Promise((resolve, reject) => {
      const id = randomUUID();
      const timer = setTimeout(() => {
        this.pending.delete(id); entry.commands = entry.commands.filter(command => command.id !== id);
        reject(new Error('CANVAS_TIMEOUT: outcome may be unknown; retry with the same requestId'));
      }, 25000);
      this.pending.set(id, { canvasId, resolve, reject, timer });
      entry.commands.push({ ...command, id }); entry.wake?.();
    });
  }
  reply(canvasId: string, commandId: string, result: { value?: unknown; error?: string }) {
    const pending = this.pending.get(commandId);
    if (!pending || pending.canvasId !== canvasId) return;
    clearTimeout(pending.timer); this.pending.delete(commandId);
    if (result.error) pending.reject(new Error(result.error)); else pending.resolve(result.value);
  }
  unregister(canvasId: string) {
    this.canvases.get(canvasId)?.wake?.(); this.canvases.delete(canvasId);
    for (const [id, pending] of this.pending) if (pending.canvasId === canvasId) {
      clearTimeout(pending.timer); pending.reject(new Error('CANVAS_UNAVAILABLE')); this.pending.delete(id);
    }
  }
  dispose() { [...this.canvases.keys()].forEach(id => this.unregister(id)); }
}
"},{"path":"infrastructure/mapping/agent/execRuntime.ts","text":"import { newAsyncContext } from 'quickjs-emscripten';
import type { AgentExecRuntime } from '../../../application/mapping/agent/ports';
import { canvasMethods } from '../../../domain/mapping/agent/contracts';
export class QuickJsAgentRuntime implements AgentExecRuntime {
  async run(code: string, invoke: (method: string, args: unknown) => Promise<unknown>) {
    const context = await newAsyncContext();
    const deadline = Date.now() + 30000;
    let interrupts = 0, calls = 0;
    context.runtime.setMemoryLimit(32 * 1024 * 1024);
    context.runtime.setMaxStackSize(512 * 1024);
    context.runtime.setInterruptHandler(() => Date.now() > deadline || ++interrupts > 20000);
    try {
      const call = context.newAsyncifiedFunction('__call', async (method, json) => {
        if (++calls > 100) throw new Error('Execution exceeds 100 API calls');
        const value = await invoke(context.getString(method), JSON.parse(context.getString(json)));
        const result = JSON.stringify(value ?? null);
        if (Buffer.byteLength(result) > 4 * 1024 * 1024) throw new Error('API result exceeds 4MB');
        return context.newString(result);
      });
      context.setProp(context.global, '__call', call); call.dispose();
      const groups = ['canvas','nodes','edges'].map(group => `const ${group} = Object.freeze({${Object.keys(canvasMethods).filter(name => name.startsWith(`${group}.`)).map(name => `${name.split('.')[1]}: (args = {}) => JSON.parse(__call(${JSON.stringify(name)}, JSON.stringify(args)))`).join(',')}});`).join('\n');
      const result = await context.evalCodeAsync(`"use strict"; ${groups}\nJSON.stringify((function() {\n${code}\n})() ?? null)`);
      if (result.error) { const error = context.dump(result.error); result.error.dispose(); throw new Error(error?.message ?? String(error)); }
      const json = context.getString(result.value); result.value.dispose();
      if (Buffer.byteLength(json) > 4 * 1024 * 1024) throw new Error('Execution result exceeds 4MB');
      return JSON.parse(json);
    } finally { context.dispose(); }
  }
}
"},{"path":"infrastructure/mapping/mcp/server.ts","text":"import { rollUpRequestSchema } from '../../../domain/mapping/rollup/rollUp';
import { generateComparisonSchema } from '../../../domain/mapping/compare/comparisonGeneration';
import { agentContextToolDefinitions } from '../../../domain/core/agents/savedAgentContext';
import { canvasViewInstructions } from '../../../domain/core/diagrams/canvasView';
import { generationSchemas, generationBatchSchemas, directBatchSchemas, directDiagramInstructions, isDiagramTool } from '../../../domain/mapping/agent/diagramBatch';
import { diagramOutputFormat } from '../../../domain/mapping/agent/promptTemplates';
import { CANVAS_EXEC_DESCRIPTION, canvasAgentInstructions } from '../../../domain/mapping/agent/capabilities';
import { z } from 'zod';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { agentToolSchemas } from '../../../domain/mapping/agent/contracts';
export function createMappingMcpServer(baseUrl: string, binding = process.env.MAPPING_CHAT_BINDING,
  target?: { canvasId: string; documentId: string }) {
  const base = new URL(baseUrl);
  if (!['http:', 'https:'].includes(base.protocol)) throw new Error('Expected Mapping backend HTTP URL');
  let attachment: Promise<string> | undefined;
  const post = async (name: string, input: unknown) => {
    const response = await fetch(new URL(`/api/mapping/agent/tools/${name}`, base), { method: 'POST',
      headers: { 'content-type': 'application/json', ...(binding ? { 'x-canvas-chat-binding': binding } : {}) },
      body: JSON.stringify(input), signal: AbortSignal.timeout(65000) });
    return { response, value: await response.json() };
  };
  const attachedSession = () => attachment ??= post('exec', { requestId: crypto.randomUUID(), code: `return canvas.attach(${JSON.stringify(target)});` })
    .then(({ response, value }) => { if (!response.ok) throw Error(value.error ?? 'Canvas attachment failed'); return value.value.sessionId as string; })
    .catch(error => { attachment = undefined; throw error; });
  const server = new McpServer({ name: 'mapping', version: '0.1.0' }, {
    instructions: (binding || target
      ? 'This persistent connection is bound to a canvas. Start with exec code return canvas.read({}); omit sessionId. Agent Chat captures the document for each turn. Do not attach elsewhere or start another MCP client. '
      : 'Use this connected MCP server directly. Call exec with return canvas.list(); then canvas.attach and pass its sessionId on later calls. Configure --canvas and --document at server startup to bind automatically. ')
      + 'Common method definitions are included in exec; use canvas-api-search only for additional APIs. ChangeSession operations require changeSessionId. Each new request needs a unique requestId. Retry uncertain outcomes with identical arguments and requestId. '
  });
  const descriptions = {
    ...Object.fromEntries(agentContextToolDefinitions.map(tool => [tool.name, tool.description])) as Record<typeof agentContextToolDefinitions[number]['name'], string>,
    get_repository_diff_hunks: 'Discover immutable Git hunks for repositoryId and selected commits before creating a ChangeSession. Returns pinned full commit SHAs, head, and stable hunk IDs. Each commit compares with its first parent (root commits with empty tree); renames are delete/add. Paginated; reuse returned SHAs on later pages and creation. includePatches false returns metadata only.',
    read_change_session_diff_tree: 'Read a ChangeSession DiffTree Diagram, stable logical nodes and mappings, plus paginated captured hunks. nodeIds resolves selected tree nodes with ancestor fallback; hunkIds selects hunks directly. Uses persisted content without rereading Git or loading canvas histories. Legacy sessions return diffTree null.',

    list_repositories: 'List registered repositories, stable IDs, names and available checkout roots. Worktrees share one repository identity.',
    register_repository: 'Register a local Git repository/worktree in this project. The same Git common directory resolves to the same repository ID. Does not move canvases or change Git history.',
    'diagram-agent-context': 'Prepare, read, or delete a reusable AgentContext bound to a live diagram. Read loads the disk-backed context and returns ready/stale status. Prepare compiles source evidence into a dedicated immutable file; delete removes the binding. Prepare/delete require expectedVersion and expectedRevisionId from a current canvas read, are undoable and persisted. Retry mutations with the same requestId.',
    'canvas-view': canvasViewInstructions,
    'edit-diagram': 'Start an asynchronous prompt-driven edit of one live diagram. Requires sessionId, nodeId, current document expectedVersion, diagram.revisionId as baseRevisionId, prompt and requestId. Optional agentContextId references a durable global context from create-agent-context, or a legacy trajectory uploaded over the connected-agent WebSocket for this workspace/document. Returns runId; poll edit-diagram-status. Required edit-mode: in-place applies one immutable child revision; variant saves the edit in a new variant without changing the live diagram. Required replace-mode (no default): diagram (omit subtree targets), subnode-single (supply subtree {contentNodeId, revisionId}), multi-contiguous (supply subtrees: at least two adjacent roots), or multi-disjoint (supply subtrees: at least two separate roots). Target revisionId is content.revisionId; use current parsed content node IDs. Each target includes its descendants. Overlaps, stale targets, and edits outside the selected ranges are rejected. Both edit modes create one undo checkpoint and flush workspace persistence. Repeat the identical request to retry an awaiting-acknowledgement run; it never regenerates. Runs and retry receipts are in memory until backend restart. Optional template and references work as in create-diagram.',
    'extend-diagram': 'Create a connected diagram at the chosen canvas origin from selected source nodes.',
  'create-diagram': 'Start an asynchronous prompt-driven creation of 1–4 new diagrams beside one live anchor diagram. Uses target, prompt, context and reference fields plus optional count; omit edit-mode, replace-mode, and subtree targets; nodeId and baseRevisionId pin the anchor whose revision and evidence are the context. Optional template {id, version, options, markdown?} and references (diagram or node ranges pinned to revisionIds, cited in the prompt as [ref N]). Poll edit-diagram-status; created.nodeIds lists the placed diagrams. Repeat the identical request to retry; it never regenerates.',
    'edit-diagram-status': 'Read a prompt-driven edit run, including progress, generated ASCII, result revision IDs, persistence acknowledgement, or conflict. Does not mutate diagrams.',
    'cancel-diagram-edit': 'Cancel a prompt-driven edit before application. Once applying or awaiting acknowledgement, cancellation does not undo or misreport a possibly committed edit; inspect its status or retry the original edit request.',
    set_diagram_source_mappings: 'Replace the complete source mappings and evidence on one diagram without resending ASCII. Requires the current document version; content validation is internal. Preserves text, node anchors and connections. Live calls update the canvas and workspace history; changeSessionId targets an isolated proposal. Omitted source preserves the repository binding.',
    accept_diagram_change_session: 'Accept an entire ready proposal only when the user explicitly asks to accept it. Atomically publishes its changed canvases, freezes the session, and retains before/after revision and checkpoint references. Rejects stale originals. Retry the same requestId and expectedVersion after transport failures. Does not erase the review diff.',
    create_diagram_change_session: 'Capture canvases owned by repositoryId as isolated proposal copies. Specify repositoryId when multiple repositories are registered. commits is an explicit set of commit refs (default empty); head defaults to the selected repository HEAD. Both are resolved to full SHAs and pinned at creation. Optional diffTree supplies ASCII and line/node-to-hunk mappings atomically; otherwise creates a default tree. Returns changeSessionId and canvasId. Pass changeSessionId to exec, diagram-search and draw_diagram for all proposal work. Does not modify or save original diagrams.',
    update_diagram_change_session: 'Session-specific metadata and history: diffTree replaces the complete hunk mapping list and optionally tree ASCII; existing trees require diffTree.expectedRevisionId plus session expectedVersion. Omission preserves DiffTree. Annotate generated changes with titles, types 1/2/3/4, reasons and dependencies; replace migrations with explicit source/destination revision-bound node or subtree endpoints (destination snapshot must be proposed); omitted migrations preserves them, [] clears them; mark ready or archive; undo/redo/reset a session document. Read session version and changes through diagram-search with changeSessionId. Ready requires valid anchors and connections for added diagrams. Does not accept or publish changes.',
    'diagram-search': 'Search diagrams by text, node, or code reference; operation read returns the complete saved or live diagram. With changeSessionId and no sessionId, snapshot baseline/proposed selects captured/proposed content (default proposed); representationId selects the session document. Returns migration metadata alongside generated changes.',
    'canvas-api-search': 'Search API documentation, schemas, coordinate rules, and examples. Does not search canvas objects.',
    exec: binding ? CANVAS_EXEC_DESCRIPTION : canvasAgentInstructions('edit'),
    draw_diagram: 'Create or replace a diagram from complete ASCII content. No reserved bounds; existing grid layout places the result.',
    save_diagram: 'Save a live diagram/document as a confirmed representation visible in explorer and search. nodeId saves one diagram independently.'
  };
  for (const name of Object.keys(agentToolSchemas) as (keyof typeof agentToolSchemas)[]) {
    // MCP requires an object at the schema root. Validate the exclusive single/batch
    // contract after resolving the connection's session, below.
    const single = isDiagramTool(name) ? generationSchemas[name] : undefined;
    const schema = binding && isDiagramTool(name) ? directBatchSchemas[name]
      : single && isDiagramTool(name) ? single.partial().extend({ sessionId: single.shape.sessionId,
        expectedVersion: single.shape.expectedVersion, requestId: single.shape.requestId,
        operations: generationBatchSchemas[name].shape.operations.optional() }).strict()
      : agentToolSchemas[name];
    const optionalSession = (schema: z.ZodType): z.ZodType => schema instanceof z.ZodUnion
      ? z.union(schema.options.map(option => optionalSession(option as z.ZodType)))
      : schema instanceof z.ZodObject && 'sessionId' in schema.shape ? schema.extend({ sessionId: z.string().optional() }) : schema;
    const description = binding && isDiagramTool(name)
      ? directDiagramInstructions(name) + diagramOutputFormat(name, 'optional', `${name} using operations[].${name === 'edit-diagram' ? 'edit' : 'diagram'}`)
      : descriptions[name] + (isDiagramTool(name) ? ' Also accepts {sessionId, expectedVersion, requestId, operations:[...]} for an atomic batch. Operations share the base snapshot; generation completes before one persisted undo step. source-mappings is optional and defaults to false.' : '');
    server.registerTool(name, { description, inputSchema: binding || target ? optionalSession(schema) : schema, annotations: { readOnlyHint: name.endsWith('search') || name === 'edit-diagram-status' || name === 'get_repository_diff_hunks' || name === 'read_change_session_diff_tree' || name === 'list_repositories' || name === 'list-agent-contexts' || name === 'read-agent-context' || name === 'read-agent-context-lineage', openWorldHint: false } }, async (input: unknown) => {
      try {
        const args = { ...(input as Record<string, unknown>) };
        if (target && !binding && !args.changeSessionId) {
          const scoped = ['exec', 'draw_diagram', 'save_diagram', 'set_diagram_source_mappings', 'edit-diagram', 'create-diagram', 'extend-diagram', 'diagram-agent-context', 'canvas-view', 'diagram-search'];
          if (scoped.includes(name) && !(name === 'diagram-search' && args.representationId)) {
            const sessionId = await attachedSession();
            if (args.sessionId && args.sessionId !== sessionId) throw Error('BINDING_MISMATCH: omit sessionId on a bound connection');
            args.sessionId = sessionId;
          }
        }
        if (!binding && isDiagramTool(name)) agentToolSchemas[name].parse(args);
        const { response, value } = await post(name, args);
        return { content: [{ type: 'text' as const, text: JSON.stringify(value) }], ...(response.ok ? { structuredContent: { result: value } } : { isError: true }) };
      } catch (error) { return { content: [{ type: 'text' as const, text: error instanceof Error ? error.message : String(error) }], isError: true }; }
    });
  }
  for (const tool of [
    { name: 'generate-roll-up', schema: rollUpRequestSchema, route: '/api/mapping/evals/roll-ups', method: 'POST', description: 'Generate a roll-up from pinned child and parent canvases. Each pass makes r2 (one diagram), then g2 (an attached copy of the parent). Defaults to one pass; two passes produce four canvases. Returns an Evals run; poll read-eval-run. Retry identical arguments and requestId.' },
    { name: 'read-eval-run', schema: z.object({ runId: z.string().uuid() }).strict(), route: '/api/mapping/evals/runs', method: 'GET', description: 'Read an Evals run and its cells, generated canvas/checkpoint IDs, errors and prompt provenance.' },
    { name: 'generate-diagram-comparisons', schema: generateComparisonSchema, route: '/api/mapping/comparison-runs', method: 'POST', description: 'Compare selected saved views using only linked ASCII diagrams. Supply sources from list-compare-candidates, title, and a unique requestId. Defaults to gpt-6-sol high. Returns run ID immediately; poll read-diagram-comparison-run for status and the saved comparison URL. Retries with the same arguments/requestId are idempotent.' },
    { name: 'read-diagram-comparison-run', schema: z.object({ runId: z.string().uuid() }).strict(), route: '/api/mapping/comparison-runs', method: 'GET', description: 'Read comparison generation status, errors, and the finished session URL.' },
    { name: 'list-compare-candidates', schema: z.object({}).strict(), route: '/api/mapping/compare-sessions/candidates', method: 'GET', description: 'List saved canvas views and their pinned checkpoints for comparison generation.' }
  ]) server.registerTool(tool.name, { description: tool.description, inputSchema: tool.schema, annotations: { readOnlyHint: tool.method === 'GET', openWorldHint: false } }, async input => {
    try {
      const args = input as Record<string, unknown>;
      const route = tool.route + (['read-diagram-comparison-run', 'read-eval-run'].includes(tool.name) ? `/${encodeURIComponent(String(args.runId))}` : '');
      const response = await fetch(new URL(route, base), { method: tool.method, headers: { 'content-type': 'application/json' },
        ...(tool.method === 'POST' ? { body: JSON.stringify(input) } : {}), signal: AbortSignal.timeout(65000) });
      const result = await response.json();
      return { content: [{ type: 'text' as const, text: JSON.stringify(result) }], ...(response.ok ? { structuredContent: { result } } : { isError: true }) };
    } catch (error) { return { content: [{ type: 'text' as const, text: String(error) }], isError: true }; }
  });
  return server;
}
/** Fetch definitions from the running host so a restarted MCP connection never uses a stale bundle. */
export async function registerChatMcpTools(server: McpServer, baseUrl: string, binding: string) {
  const headers = { 'content-type': 'application/json', 'x-canvas-chat-binding': binding };
  const response = await fetch(new URL('/api/mapping/agent-chat/tools', baseUrl), { headers, signal: AbortSignal.timeout(15000) });
  if (!response.ok) throw Error('Could not load Agent Chat tool definitions.');
  const definitions = await response.json() as import('../../../application/mapping/agent-chat/ports').ChatTools['definitions'];
  for (const tool of definitions) {
    const schema = z.fromJSONSchema(tool.inputSchema);
    if (!(schema instanceof z.ZodObject)) throw Error(`Expected an object schema for ${tool.name}`);
    server.registerTool(`chat_${tool.name}`, { description: tool.description, inputSchema: schema }, async (input: unknown, extra) => {
      try {
        const result = await fetch(new URL(`/api/mapping/agent-chat/tools/${tool.name}`, baseUrl), { method: 'POST', headers,
          body: JSON.stringify({ input, callId: `mcp:${extra.requestId}` }), signal: AbortSignal.timeout(65000) });
        const value = await result.json();
        return { content: [{ type: 'text' as const, text: JSON.stringify(value) }],
          ...(result.ok ? { structuredContent: { result: value } } : { isError: true }) };
      } catch (error) { return { content: [{ type: 'text' as const, text: String(error) }], isError: true }; }
    });
  }
}
export async function startMappingMcpServer(baseUrl: string, target?: { canvasId: string; documentId: string }) {
  const binding = process.env.MAPPING_CHAT_BINDING;
  const server = createMappingMcpServer(baseUrl, binding, target);
  if (binding) await registerChatMcpTools(server, baseUrl, binding);
  await server.connect(new StdioServerTransport());
}
"},{"path":"src/features/mapping/agent/useAgentCanvasBridge.ts","text":"import { canvasReply, mutationCommands } from '../../../../domain/mapping/agent/canvasReply';
import { publishLiveCanvasSelections, type LiveAgentStatus } from './liveCanvasPublisher';
import type { CanvasWorkspace } from '../workspace/canvasWorkspace';
import { useEffect, useRef, useState } from 'react';
import type { CanvasCommand, CanvasDescriptor } from '../../../../domain/mapping/agent/contracts';
import { apiFetch, errorFrom } from '../../../shared/http/http';
import { browserStableWorkspaceId } from './stableWorkspaceIdentity';

export function useAgentCanvasBridge(descriptor: Omit<CanvasDescriptor, 'canvasId' | 'stableWorkspaceId'>, handle: (command: CanvasCommand) => Promise<unknown>, workspace?: CanvasWorkspace, canMutate: () => boolean = () => true) {
  const [agentStatus, setAgentStatus] = useState<LiveAgentStatus>({ connected: false, count: 0 });
  const [canvasId] = useState(() => crypto.randomUUID());
  const [identity, setIdentity] = useState<{ stableWorkspaceId?: string }>();
  useEffect(() => {
    let active = true;
    void browserStableWorkspaceId(import.meta.env.BASE_URL).then(stableWorkspaceId => {
      if (active) setIdentity({ stableWorkspaceId });
    });
    return () => { active = false; };
  }, []);
  const latest = useRef({ descriptor, handle, canMutate }); latest.current = { descriptor, handle, canMutate };
  const registration = identity && JSON.stringify({ ...descriptor, canvasId, ...identity });
  useEffect(() => {
    if (!registration) return;
    void apiFetch('/api/mapping/agent/canvases', { method: 'POST', headers: { 'content-type': 'application/json' }, body: registration }).catch(() => undefined);
  }, [registration]);
  useEffect(() => {
    if (!identity) return;
    const abort = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    const results = new Map<string, { value?: unknown; error?: string }>();
    const request = async (path: string, body?: unknown, method = body === undefined ? 'GET' : 'POST') => {
      const response = await apiFetch(`/api/mapping/agent${path}`, { method, signal: abort.signal,
        ...(body === undefined ? {} : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }) });
      if (!response.ok) throw await errorFrom(response);
      return response.json();
    };
    const register = () => request('/canvases', { ...latest.current.descriptor, canvasId, ...identity });
    const run = async () => {
      try {
        await register();
        while (!abort.signal.aborted) {
          const commands: CanvasCommand[] = await request(`/canvases/${canvasId}/commands`);
          for (const command of commands) {
            const started = performance.now();
            let result = results.get(command.id);
            if (!result) {
              try { result = { value: await latest.current.handle(command) }; }
              catch (error) { result = { error: error instanceof Error ? error.message : String(error) }; }
              if (mutationCommands.has(command.method)) results.set(command.id, result);
              if (results.size > 200) results.delete(results.keys().next().value!);
            }
            const handled = performance.now();
            const reply = canvasReply(command, result);
            const encoded = performance.now();
            const response = await apiFetch(`/api/mapping/agent/canvases/${canvasId}/reply`, { method: 'POST', signal: abort.signal,
              headers: { 'content-type': 'application/json', 'x-canvas-command-id': command.id }, body: reply.body });
            if (!response.ok) {
              // A proxy/backend can enforce a lower limit. Resolve the pending command immediately.
              await request(`/canvases/${canvasId}/reply`, { commandId: command.id,
                error: `CANVAS_REPLY_REJECTED: method=${command.method} actualBytes=${reply.bytes} status=${response.status}; retry the identical requestId if this was a mutation` });
            }
            console.debug('canvas-reply', { method: command.method, bytes: reply.bytes, handleMs: Math.round(handled - started), encodeMs: Math.round(encoded - handled), replyMs: Math.round(performance.now() - encoded), durationMs: Math.round(performance.now() - started), oversized: reply.oversized });
          }
          await register();
        }
      } catch {
        if (!abort.signal.aborted) timer = setTimeout(() => void run(), 1000);
      }
    };
    void run();
    const unregister = () => { void apiFetch(`/api/mapping/agent/canvases/${canvasId}`, { method: 'DELETE', keepalive: true }).catch(() => undefined); };
    // React cleanup does not run on page reload. Retire this ephemeral instance
    // promptly, without ever deleting a replacement that has the same stable ID.
    window.addEventListener('pagehide', unregister);
    return () => { abort.abort(); clearTimeout(timer); window.removeEventListener('pagehide', unregister); unregister(); };
  }, [canvasId, identity]);
  useEffect(() => {
    setAgentStatus({ connected: false, count: 0 });
    if (!workspace || !identity) return;
    const endpoint = new URL(`${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/mapping/live`, location.href);
    endpoint.protocol = endpoint.protocol === 'https:' ? 'wss:' : 'ws:';
    return publishLiveCanvasSelections(workspace, canvasId, endpoint.href, setAgentStatus, () => latest.current.canMutate());
  }, [workspace, canvasId, identity]);
  return { canvasId, agentStatus };
}
