162:   }
163:   publish(owner: object, workspaceInstanceId: string, notify: (event: LiveCanvasEvent) => void = () => {}, capabilities: readonly string[] = []) {
164:     if (!this.listCanvases().some(c => c.canvasId === workspaceInstanceId)) throw new LiveCanvasError('CANVAS_UNAVAILABLE', 503);
165:     if (this.publishers.has(workspaceInstanceId)) throw new LiveCanvasError('PUBLISHER_EXISTS', 409);
166:     this.publishers.set(workspaceInstanceId, { owner, capabilities: new Set(capabilities), selections: new Map(), notify });
167:   }
168:   update(owner: object, workspaceInstanceId: string, update: LiveSelection | LiveSelectionDelta) {
169:     const publisher = this.publisher(owner, workspaceInstanceId);
170:     const previous = publisher.selections.get(update.documentId);
171:     if (previous?.canvasEpoch === update.canvasEpoch && update.sequence <= previous.sequence) return;
172:     if (!previous && publisher.selections.size >= 100) throw new LiveCanvasError('DOCUMENT_LIMIT', 400);
173:     let selection: LiveSelection;
174:     if ('regions' in update) selection = update;
175:     else {
176:       if (!previous || previous.canvasEpoch !== update.canvasEpoch || previous.sequence !== update.baseSequence)
177:         throw new LiveCanvasError('SELECTION_OUT_OF_SYNC', 409, 'Reconnect and publish a fresh snapshot');
178:       if (new Set(update.upserted.map(region => region.id)).size !== update.upserted.length
179:         || new Set(update.removed).size !== update.removed.length
180:         || update.upserted.some(region => update.removed.includes(region.id)))
181:         throw new LiveCanvasError('INVALID_REGIONS', 400);
182:       const regions = new Map(previous.regions.map(region => [region.id, region]));
183:       update.removed.forEach(id => regions.delete(id));
184:       update.upserted.forEach(region => regions.set(region.id, region));
185:       selection = { documentId: update.documentId, canvasEpoch: update.canvasEpoch, sequence: update.sequence,
186:         documentVersion: update.documentVersion, regions: [...regions.values()], diagramIds: update.diagramIds ?? previous.diagramIds ?? [] };
187:     }
188:     const diagramIds = selection.diagramIds ?? [];
189:     if (diagramIds.length > 1000 || new Set(diagramIds).size !== diagramIds.length
190:       || diagramIds.some(id => !id.startsWith('grid:'))
191:       || selection.regions.some(region => diagramIds.includes(`grid:${region.sourceBoxId}`)))
192:       throw new LiveCanvasError('INVALID_REGIONS', 400, 'Whole diagrams replace their regions and must have unique grid IDs');
193:     if (selection.regions.length > 1000 || new Set(selection.regions.map(region => region.id)).size !== selection.regions.length
194:       || selection.regions.reduce((size, region) => size + region.text.length, 0) > 2_000_000)
195:       throw new LiveCanvasError('INVALID_REGIONS', 400, 'Regions must have unique IDs and fit the canvas payload limit');
196:     if (previous && previous.canvasEpoch !== selection.canvasEpoch) this.invalidate(workspaceInstanceId, selection.documentId, 'canvas.replaced');
197:     const receivedAt = new Date().toISOString();
198:     publisher.selections.set(selection.documentId, { ...selection, receivedAt });
199:     if (previous && previous.canvasEpoch === selection.canvasEpoch) {
200:       const delta = selectionDelta(previous, selection);
201:       for (const [connectionId, binding] of this.bindings) if (!binding.unavailable && binding.workspaceInstanceId === workspaceInstanceId
202:         && binding.documentId === selection.documentId) binding.notify({ type: 'selection.delta', ...delta, connectionId, workspaceInstanceId, receivedAt });
203:     }
204:   }
205:   remove(owner: object, workspaceInstanceId: string, documentId: string, canvasEpoch: string) {
206:     const publisher = this.publisher(owner, workspaceInstanceId);
207:     if (publisher.selections.get(documentId)?.canvasEpoch !== canvasEpoch) return;
208:     publisher.selections.delete(documentId);
209:     this.invalidate(workspaceInstanceId, documentId, 'canvas.closed');
210:   }
211:   attach(workspaceInstanceId: string, documentId: string, notify: Binding['notify']): BoundSelection {
212:     const selection = this.publishers.get(workspaceInstanceId)?.selections.get(documentId);
213:     if (!selection) throw new LiveCanvasError('CANVAS_NOT_READY', 503, 'Canvas has not published a selection snapshot; retry attach');
214:     const connectionId = randomUUID();
215:     this.bindings.set(connectionId, { workspaceInstanceId, documentId, canvasEpoch: selection.canvasEpoch, notify });
216:     this.notifyAgents(workspaceInstanceId);
217:     return this.read(connectionId);
218:   }
219:   read(connectionId: string): BoundSelection {
220:     const binding = this.bindings.get(connectionId);
221:     if (!binding) throw new LiveCanvasError('CONNECTION_NOT_FOUND', 404);
222:     if (binding.unavailable) throw new LiveCanvasError(binding.unavailable, binding.unavailable === 'canvas.disconnected' ? 503 : 410);
223:     const selection = this.publishers.get(binding.workspaceInstanceId)?.selections.get(binding.documentId);
224:     if (!selection || selection.canvasEpoch !== binding.canvasEpoch) throw new LiveCanvasError('CANVAS_UNAVAILABLE', 503);
225:     return { ...selection, protocolVersion: 2, connectionId, workspaceInstanceId: binding.workspaceInstanceId };
226:   }
227:   detach(connectionId: string) {
228:     const binding = this.bindings.get(connectionId);
229:     if (!binding) return;
230:     this.bindings.delete(connectionId);
231:     if (!binding.unavailable) this.notifyAgents(binding.workspaceInstanceId);
232:   }
233:   private notifyAgents(workspaceInstanceId: string) {
234:     const count = [...this.bindings.values()].filter(binding => binding.workspaceInstanceId === workspaceInstanceId && !binding.unavailable).length;
235:     this.publishers.get(workspaceInstanceId)?.notify({ type: 'agents.changed', count });
236:   }
237:   disconnect(owner: object, workspaceInstanceId: string) {
238:     if (this.publishers.get(workspaceInstanceId)?.owner !== owner) return;
239:     this.publishers.delete(workspaceInstanceId);
240:     this.invalidate(workspaceInstanceId, undefined, 'canvas.disconnected');
241:   }
242:   private publisher(owner: object, id: string) {
243:     const publisher = this.publishers.get(id);
244:     if (!publisher || publisher.owner !== owner) throw new LiveCanvasError('PUBLISHER_UNAVAILABLE', 503);
245:     return publisher;
246:   }
247:   private invalidate(workspaceInstanceId: string, documentId: string | undefined, reason: NonNullable<Binding['unavailable']>) {
248:     for (const receipt of this.copies.values()) if (receipt.workspaceInstanceId === workspaceInstanceId
249:       && (!documentId || receipt.command.documentId === documentId) && receipt.pending) {
250:       clearTimeout(receipt.pending.timer); receipt.pending.reject(new LiveCanvasError(reason, 410)); receipt.pending = undefined;
251:     }
252:     for (const receipt of this.pastes.values()) if (receipt.workspaceInstanceId === workspaceInstanceId
253:       && (!documentId || receipt.command.documentId === documentId) && receipt.pending) {
254:       clearTimeout(receipt.pending.timer);
255:       receipt.pending.reject(new LiveCanvasError(reason, 410, `${reason}: outcome may be unknown; rediscover before retrying`));
256:       receipt.pending = undefined;
257:     }
258:     let changed = false;
259:     for (const [connectionId, binding] of this.bindings) if (!binding.unavailable && binding.workspaceInstanceId === workspaceInstanceId
260:       && (!documentId || binding.documentId === documentId)) {
261:       changed = true;
262:       binding.unavailable = reason;
263:       binding.notify({ type: reason, connectionId, canvasEpoch: binding.canvasEpoch });
264:     }
265:     if (changed) this.notifyAgents(workspaceInstanceId);
266:   }
267: }
